```sql
select 100 * (permits / permits_single_family) as value from doorstep.fct_metro_year where cbsa_title = 'Savannah, GA' and year = 2021 group by cbsa_title order by value desc;
```

```sql
select 100 * (households / households_moe) as value from doorstep.ch8_metros where cbsa_title = 'Scranton--Wilkes-Barre, PA' and year = 2023 group by cbsa_title order by value desc, label;
```

```sql
select payment_share from doorstep.mart_metro_year where cbsa_title = 'Asheville, NC' and year = 2015 order by payment_share desc;
```

```sql
select anchor_value_moe as value from doorstep.fct_metro_year where cbsa_title = 'Beaumont-Port Arthur, TX' and year = 2009 and cbsa_code = 'BPA' order by value desc;
```

```sql
select 100 * (renter_burdened_share / renter_median_income) as value from doorstep.mart_metro_year where cbsa_title = 'Winston-Salem, NC' and year = 2012 group by cbsa_title order by value desc;
```

```sql
select cbsa_code, permits from doorstep.fct_metro_year where cbsa_title in ('Stockton-Lodi, CA', 'Fayetteville, NC') and year = 2017 group by cbsa_code order by permits desc;
```

```sql
select count(*) as value from doorstep.mart_metro_year where year = 2011 and median_value_reported > 130000;
```

```sql
select anchor_value as value from doorstep.mart_metro_year where cbsa_title = 'Des Moines-West Des Moines, IA' and year = 2020 group by cbsa_title order by value desc;
```

```sql
select count(*) as value from turnaround.export_ch2_by_carrier where carrier = 'Mesa' and month = 2015;
```

```sql
select 100 * max(payment_share) as value from doorstep.export_ch1_anchor_sensitivity where year between 2015 and 2024 group by year order by value desc, year;
```

```sql
select 100 * max(provision) as value from ledger.metrics_bank_quarter where period in ('2023Q4', '2024Q1', '2025Q2', '2026Q1') group by period order by value desc;
```

```sql
select 100 * (sum(anchor_value_moe) / sum(anchor_value)) as value from doorstep.mart_metro_year where year = 2014 and anchor_value_moe > 0 order by value desc;
```

```sql
select 100 * (net_interest_income / (net_interest_income + net_income)) as value from doorstep.mart_metro_year where year = 2024 and period = 'Q2' and quarter = '2' order by value desc;
```

```sql
select permit_rate from doorstep.fct_metro_year where cbsa_code = 'Hilton Head Island-Bluffton-Port Royal, SC' and year between 2008 and 2014 group by cbsa_code order by year asc;
```
